"""Plan (and later perform) downloads of the pinned Hugging Face snapshots.

``plan_snapshot`` resolves exactly which files ``snapshot_download`` would fetch for a pin, using
the same pattern filter, so ``flora prepare --dry-run`` shows sizes before anything is downloaded.
"""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass, field
from typing import Protocol

from huggingface_hub.utils import filter_repo_objects

from flora_deploy.config.pins import PINS, RepoPin


@dataclass(frozen=True)
class FileEntry:
    path: str
    size: int
    lfs_sha256: str | None


@dataclass(frozen=True)
class SnapshotPlan:
    pin: RepoPin
    files: tuple[FileEntry, ...] = field(default_factory=tuple)

    @property
    def total_bytes(self) -> int:
        return sum(f.size for f in self.files)


class TreeLister(Protocol):
    def list_repo_tree(self, repo_id: str, *, revision: str, recursive: bool) -> Iterable: ...


def plan_snapshot(pin: RepoPin, api: TreeLister) -> SnapshotPlan:
    entries = [
        e
        for e in api.list_repo_tree(pin.repo, revision=pin.revision, recursive=True)
        if not hasattr(e, "tree_id")  # skip RepoFolder entries
    ]
    selected = filter_repo_objects(
        entries,
        allow_patterns=list(pin.allow_patterns) if pin.allow_patterns else None,
        key=lambda e: e.path,
    )
    files = tuple(
        sorted(
            (
                FileEntry(
                    path=e.path,
                    size=int(e.size or 0),
                    lfs_sha256=getattr(e.lfs, "sha256", None) if e.lfs else None,
                )
                for e in selected
            ),
            key=lambda f: f.path,
        )
    )
    return SnapshotPlan(pin=pin, files=files)


def plan_all(api: TreeLister, pins: Iterable[RepoPin] = PINS) -> list[SnapshotPlan]:
    return [plan_snapshot(p, api) for p in pins]

import os
from pathlib import Path

import pytest

from flora_deploy.config.pins import PINS_BY_KEY
from flora_deploy.layout import NV_CODE_CACHE_DEFAULT, NV_CODE_CACHE_ENV, snapshot_dirname


def _nv_root() -> Path:
    return Path(os.environ.get(NV_CODE_CACHE_ENV, NV_CODE_CACHE_DEFAULT)).expanduser()


@pytest.fixture
def nv_code():
    """Return the local dir of a fetched NVIDIA code pin, or skip.

    Usage: ``nv_code("tempseg_code")`` / ``nv_code("captioner_code")`` / ``nv_code("rewarder")``.
    Fetch with ``uv run python scripts/fetch_nv_code.py [--with-processor]``.
    """

    def get(key: str) -> Path:
        path = _nv_root() / snapshot_dirname(PINS_BY_KEY[key])
        if not (path / "batch_utils").is_dir():
            pytest.skip(f"NVIDIA code pin {key!r} not fetched (scripts/fetch_nv_code.py)")
        return path

    return get

import json
from dataclasses import dataclass

from typer.testing import CliRunner

from flora_deploy import cli
from flora_deploy.config.pins import RepoPin
from flora_deploy.prep.download import plan_all, plan_snapshot


@dataclass
class Lfs:
    sha256: str


@dataclass
class File:
    path: str
    size: int
    lfs: Lfs | None = None


@dataclass
class Folder:
    path: str
    tree_id: str = "t"


class FakeApi:
    def __init__(self, entries):
        self.entries = entries
        self.calls = []

    def list_repo_tree(self, repo_id, *, revision, recursive):
        self.calls.append((repo_id, revision, recursive))
        return list(self.entries)


ENTRIES = [
    Folder("batch_utils"),
    File("batch_utils/pipeline.py", 100),
    File("batch_utils/vendor/fine_temporal.py", 200),
    File("config.json", 10),
    File("model-00001-of-00002.safetensors", 5_000, Lfs("a" * 64)),
    File("model-00002-of-00002.safetensors", 7_000, Lfs("b" * 64)),
    File("LICENSE.pdf", 50),
    File("unrelated.bin", 1),
]


def pin(patterns):
    return RepoPin(key="k", repo="org/repo", revision="0" * 40, role="weights",
                   allow_patterns=patterns)


def test_filters_like_snapshot_download_and_skips_folders():
    plan = plan_snapshot(pin(("config.json", "model-*.safetensors")), FakeApi(ENTRIES))
    assert [f.path for f in plan.files] == [
        "config.json",
        "model-00001-of-00002.safetensors",
        "model-00002-of-00002.safetensors",
    ]
    assert plan.total_bytes == 12_010
    assert plan.files[1].lfs_sha256 == "a" * 64


def test_directory_glob_matches_nested_files():
    plan = plan_snapshot(pin(("batch_utils/*",)), FakeApi(ENTRIES))
    assert [f.path for f in plan.files] == [
        "batch_utils/pipeline.py",
        "batch_utils/vendor/fine_temporal.py",
    ]


def test_no_patterns_means_whole_snapshot():
    plan = plan_snapshot(pin(None), FakeApi(ENTRIES))
    assert len(plan.files) == 7


def test_queries_pinned_revision_recursively():
    api = FakeApi(ENTRIES)
    plan_all(api, [pin(None)])
    assert api.calls == [("org/repo", "0" * 40, True)]


def test_cli_dry_run_json(monkeypatch):
    monkeypatch.setattr(cli, "_hf_api", lambda: FakeApi(ENTRIES))
    result = CliRunner().invoke(cli.app, ["prepare", "--dry-run", "--json"])
    assert result.exit_code == 0, result.output
    rows = json.loads(result.output)
    assert {r["key"] for r in rows} >= {"tempseg", "captioner", "rewarder"}


def test_cli_refuses_real_download_for_now():
    result = CliRunner().invoke(cli.app, ["prepare"])
    assert result.exit_code == 2

import re

from flora_deploy.config.pins import PINS, PINS_BY_KEY

SHA = re.compile(r"^[0-9a-f]{40}$")


def test_every_pin_is_a_full_commit_sha():
    for pin in PINS:
        assert SHA.match(pin.revision), pin.key


def test_keys_are_unique():
    assert len(PINS_BY_KEY) == len(PINS)


def test_each_nvidia_family_has_weights_and_code():
    roles = {p.key: p.role for p in PINS}
    assert roles["tempseg"] == "weights" and roles["tempseg_code"] == "code"
    assert roles["captioner"] == "weights" and roles["captioner_code"] == "code"
    assert roles["rewarder"] == "weights+code"
